package common

import("bytes";"encoding/json";"fmt";"net/http")
type GoogleChatAdapter struct{Token string;Client *http.Client}
func(a GoogleChatAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){message,_:=payload["message"].(map[string]any);if message==nil{message=payload};sender,_:=message["sender"].(map[string]any);user,_:=sender["name"].(string);if user==""{user=fmt.Sprint(payload["user_id"])};space,_:=payload["space"].(map[string]any);room,_:=space["name"].(string);if room==""{room=fmt.Sprint(payload["space_name"])};if user==""||room==""{return InboundEvent{},fmt.Errorf("Google Chat event has no sender or space")};event:=InboundEvent{Platform:"google_chat",UserID:user,ReplyTarget:room,ContentType:"text"};event.Text,_=message["text"].(string);return event,nil}
func(a GoogleChatAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{data,_:=json.Marshal(map[string]string{"text":message.Text});req,_:=http.NewRequest(http.MethodPost,"https://chat.googleapis.com/v1/"+event.ReplyTarget+"/messages",bytes.NewReader(data));req.Header.Set("Authorization","Bearer "+a.Token);req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Google Chat API returned %s",resp.Status)}};return nil}
